import { type LucideIcon } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { useCountUp } from "@/hooks/use-count-up";
import { cn } from "@/lib/utils";
import { TrendingUp, TrendingDown } from "lucide-react";

interface KpiCardProps {
  title: string;
  value: number;
  prefix?: string;
  suffix?: string;
  trend?: number;
  trendLabel?: string;
  icon: LucideIcon;
  iconColor?: string;
  iconBg?: string;
  valueColor?: string;
}

export function KpiCard({
  title,
  value,
  prefix = "",
  suffix = "",
  trend,
  trendLabel = "vs last month",
  icon: Icon,
  iconColor = "text-primary",
  iconBg = "bg-primary/8",
  valueColor = "text-foreground",
}: KpiCardProps) {
  const animatedValue = useCountUp(value);
  const isPositiveTrend = trend !== undefined && trend > 0;

  return (
    <Card className="border-border/50 shadow-soft hover:shadow-soft-md transition-shadow duration-200">
      <CardContent className="p-5">
        <div className="flex items-start justify-between">
          <div className="space-y-1.5">
            <p className="text-xs font-medium text-muted-foreground tracking-wide">
              {title}
            </p>
            <p className={cn("text-3xl font-semibold leading-none tracking-tight tabular-nums", valueColor)}>
              {prefix}{animatedValue.toLocaleString()}{suffix}
            </p>
          </div>
          <div className={cn("flex h-9 w-9 items-center justify-center rounded-lg", iconBg)}>
            <Icon className={cn("h-4 w-4", iconColor)} />
          </div>
        </div>
        {trend !== undefined && (
          <div className="mt-3 flex items-center gap-1.5">
            {isPositiveTrend ? (
              <TrendingUp className="h-3 w-3 text-emerald-500" />
            ) : (
              <TrendingDown className="h-3 w-3 text-red-500" />
            )}
            <span
              className={cn(
                "text-xs font-medium",
                isPositiveTrend ? "text-emerald-600" : "text-red-600"
              )}
            >
              {isPositiveTrend ? "+" : ""}
              {trend}%
            </span>
            <span className="text-xs text-muted-foreground">{trendLabel}</span>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useEffect, useState } from "react";
import { getScoreHex, getScoreLabel } from "@/lib/score-utils";
import { cn } from "@/lib/utils";

interface ScoreRingProps {
  score: number;
  size?: number;
  strokeWidth?: number;
  showLabel?: boolean;
  className?: string;
}

export const ScoreRing = React.forwardRef<HTMLDivElement, ScoreRingProps>(function ScoreRing({
  score,
  size = 120,
  strokeWidth = 8,
  showLabel = true,
  className,
}, ref) {
  const [animatedOffset, setAnimatedOffset] = useState(0);
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const targetOffset = circumference * (1 - score / 100);

  useEffect(() => {
    setAnimatedOffset(circumference);
    const timer = setTimeout(() => setAnimatedOffset(targetOffset), 50);
    return () => clearTimeout(timer);
  }, [score, circumference, targetOffset]);

  const color = getScoreHex(score);
  const label = getScoreLabel(score);
  const center = size / 2;
  const fontSize = size * 0.28;
  const labelSize = size * 0.09;

  // Glow shadow based on score color
  const glowShadow = score >= 70
    ? "drop-shadow(0 0 6px rgba(34, 197, 94, 0.2))"
    : score >= 40
    ? "drop-shadow(0 0 6px rgba(245, 158, 11, 0.2))"
    : "drop-shadow(0 0 6px rgba(239, 68, 68, 0.2))";

  return (
    <div
      ref={ref}
      role="img"
      aria-label={`CRO Score: ${score} out of 100`}
      className={cn("relative inline-flex flex-col items-center", className)}
    >
      <svg
        width={size}
        height={size}
        className="transform -rotate-90"
        style={{ filter: glowShadow }}
      >
        {/* Background circle */}
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeWidth={strokeWidth}
          className="text-muted/60"
        />
        {/* Score circle */}
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={animatedOffset}
          style={{ transition: "stroke-dashoffset 1s ease-out" }}
        />
      </svg>
      {/* Score number centered */}
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span
          className="font-semibold text-foreground tabular-nums"
          style={{ fontSize: `${fontSize}px`, lineHeight: 1 }}
        >
          {score}
        </span>
        <span
          className="text-muted-foreground"
          style={{ fontSize: `${labelSize}px` }}
        >
          /100
        </span>
      </div>
      {showLabel && (
        <span
          className="mt-1 text-xs font-medium"
          style={{ color }}
        >
          {label}
        </span>
      )}
    </div>
  );
});

