import { useState, useRef, useEffect } from "react";
import { Link } from "react-router-dom";
import { ChevronDown, Sparkles, Zap, TrendingUp, Copy, Check, Lock } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { SeverityBadge } from "./SeverityBadge";
import { PremiumLock } from "./PremiumLock";
import { cn } from "@/lib/utils";
import { getEffortLabel, getEffortColor } from "@/lib/score-utils";
import { useAuth } from "@/contexts/AuthContext";
import type { Finding } from "@/types";

function CopyInline({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);

  const handleCopy = async () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    try { await navigator.clipboard.writeText(text); } catch { /* fallback */ }
    setCopied(true);
    timerRef.current = setTimeout(() => setCopied(false), 2000);
  };
  return (
    <button
      onClick={handleCopy}
      className={cn(
        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-2xs font-medium border transition-all",
        copied
          ? "bg-green-50 text-green-600 border-green-200"
          : "bg-card text-muted-foreground border-border/50 hover:bg-muted/40 hover:text-foreground"
      )}
    >
      {copied ? <><Check className="h-2.5 w-2.5" />Copied</> : <><Copy className="h-2.5 w-2.5" />Copy</>}
    </button>
  );
}

interface FindingCardProps {
  finding: Finding;
  className?: string;
}

export function FindingCard({ finding, className }: FindingCardProps) {
  const [expanded, setExpanded] = useState(!finding.is_premium);
  const { profile } = useAuth();
  const isPaidPlan = profile?.plan === "pro" || profile?.plan === "agency";

  const borderColor = {
    critical: "border-l-red-500",
    warning: "border-l-amber-500",
    info: "border-l-blue-500",
    passed: "border-l-green-500",
  }[finding.severity];

  const content = (
    <Card
      className={cn(
        "border-l-4 border-border/50 shadow-soft transition-shadow hover:shadow-soft-md",
        borderColor,
        className
      )}
    >
      <CardContent className="p-5">
        {/* Header */}
        <div className="flex items-start justify-between gap-3">
          <div className="flex flex-wrap items-center gap-2">
            <SeverityBadge severity={finding.severity} />
            <h4 className="text-sm font-semibold text-foreground">{finding.title}</h4>
          </div>
          <div className="flex items-center gap-1.5 shrink-0">
            {/* Effort badge */}
            <span className={cn(
              "hidden sm:inline-flex items-center gap-0.5 rounded-full border px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide",
              getEffortColor(finding.effort)
            )}>
              <Zap className="h-2.5 w-2.5" />
              {getEffortLabel(finding.effort)}
            </span>
            {/* Lift badge */}
            {finding.estimated_lift && finding.estimated_lift !== "0%" && (
              <span className="hidden sm:inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide text-violet-600">
                <TrendingUp className="h-2.5 w-2.5" />
                {finding.estimated_lift}
              </span>
            )}
            <button
              onClick={() => setExpanded(!expanded)}
              className="rounded-md p-1 hover:bg-muted/50 transition-colors"
            >
              <ChevronDown className={cn(
                "h-4 w-4 text-muted-foreground transition-transform duration-200",
                expanded && "rotate-180"
              )} />
            </button>
          </div>
        </div>

        {/* Mobile effort/lift badges */}
        <div className="mt-2 flex flex-wrap gap-1.5 sm:hidden">
          <span className={cn(
            "inline-flex items-center gap-0.5 rounded-full border px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide",
            getEffortColor(finding.effort)
          )}>
            <Zap className="h-2.5 w-2.5" />
            {getEffortLabel(finding.effort)}
          </span>
          {finding.estimated_lift && finding.estimated_lift !== "0%" && (
            <span className="inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide text-violet-600">
              <TrendingUp className="h-2.5 w-2.5" />
              {finding.estimated_lift}
            </span>
          )}
        </div>

        {expanded && (
          <div className="mt-4 space-y-4 animate-fade-in">
            {/* Current state */}
            <div>
              <p className="mb-1.5 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
                What we found
              </p>
              <div className="rounded-lg bg-muted/40 p-3.5 text-sm text-foreground/80 leading-relaxed">
                {finding.current_state}
              </div>
            </div>

            {/* Recommendation */}
            <div>
              <p className="mb-1.5 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
                How to fix it
              </p>
              <p className="text-sm text-foreground leading-relaxed">
                {finding.recommendation}
              </p>
            </div>

            {/* AI Suggestion */}
            {finding.ai_suggestion && (
              <div className="relative rounded-lg border border-indigo-100 bg-indigo-50 p-3.5">
                <div className="mb-1.5 flex items-center justify-between">
                  <div className="flex items-center gap-1.5">
                    <Sparkles className="h-3.5 w-3.5 text-indigo-600" />
                    <p className="text-xs font-semibold uppercase tracking-widest text-indigo-700">
                      AI Suggestion
                    </p>
                  </div>
                  {isPaidPlan && <CopyInline text={finding.ai_suggestion} />}
                </div>
                {isPaidPlan ? (
                  <p className="text-sm text-slate-700 leading-relaxed whitespace-pre-line">
                    {finding.ai_suggestion}
                  </p>
                ) : (
                  <div className="relative">
                    {/* Blurred preview */}
                    <p className="select-none text-sm text-slate-700 leading-relaxed whitespace-pre-line blur-sm pointer-events-none">
                      {finding.ai_suggestion}
                    </p>
                    {/* Lock overlay */}
                    <div className="absolute inset-0 flex flex-col items-center justify-center gap-2">
                      <Lock className="h-4 w-4 text-indigo-500" />
                      <Button
                        asChild
                        size="sm"
                        className="h-7 rounded-lg bg-indigo-600 px-3 text-xs text-white hover:bg-indigo-700"
                      >
                        <Link to="/pricing">Upgrade to Pro</Link>
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Meta: category + effort on mobile */}
            <div className="flex items-center gap-3 text-xs text-muted-foreground">
              <span>Category: <span className="font-medium text-foreground">{finding.category}</span></span>
              <span>&middot;</span>
              <span>Effort: <span className="font-medium text-foreground">{getEffortLabel(finding.effort)}</span></span>
              {finding.estimated_lift && finding.estimated_lift !== "0%" && (
                <>
                  <span>&middot;</span>
                  <span>Expected lift: <span className="font-medium text-foreground">{finding.estimated_lift}</span></span>
                </>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );

  if (finding.is_premium) {
    return <PremiumLock>{content}</PremiumLock>;
  }

  return content;
}

