            "inline-flex items-center gap-0.5 rounded-full border px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide",
            getEffortColor(finding.effort)
          )}>
            <Zap className="h-2.5 w-2.5" />
            {getEffortLabel(finding.effort)}
          </span>
          {finding.estimated_lift && finding.estimated_lift !== "0%" && (
            <span className="inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide text-violet-600">
              <TrendingUp className="h-2.5 w-2.5" />
              {finding.estimated_lift}
            </span>
          )}
        </div>

        {expanded && (
          <div className="mt-4 space-y-4 animate-fade-in">
            {/* Current state */}
            <div>
              <p className="mb-1.5 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
                What we found
              </p>
              <div className="rounded-lg bg-muted/40 p-3.5 text-sm text-foreground/80 leading-relaxed">
                {finding.current_state}
              </div>
            </div>

            {/* Recommendation */}
            <div>
              <p className="mb-1.5 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
                How to fix it
              </p>
              <p className="text-sm text-foreground leading-relaxed">
                {finding.recommendation}
              </p>
            </div>

            {/* AI Suggestion */}
            {finding.ai_suggestion && (
              <div className="relative rounded-lg border border-indigo-100 bg-indigo-50 p-3.5">
                <div className="mb-1.5 flex items-center justify-between">
                  <div className="flex items-center gap-1.5">
                    <Sparkles className="h-3.5 w-3.5 text-indigo-600" />
                    <p className="text-xs font-semibold uppercase tracking-widest text-indigo-700">
                      AI Suggestion
                    </p>
                  </div>
                  {isPaidPlan && <CopyInline text={finding.ai_suggestion} />}
                </div>
                {isPaidPlan ? (
                  <p className="text-sm text-slate-700 leading-relaxed whitespace-pre-line">
                    {finding.ai_suggestion}
                  </p>
                ) : (
                  <div className="relative">
                    {/* Blurred preview */}
                    <p className="select-none text-sm text-slate-700 leading-relaxed whitespace-pre-line blur-sm pointer-events-none">
                      {finding.ai_suggestion}
                    </p>
                    {/* Lock overlay */}
                    <div className="absolute inset-0 flex flex-col items-center justify-center gap-2">
                      <Lock className="h-4 w-4 text-indigo-500" />
                      <Button
                        asChild
                        size="sm"
                        className="h-7 rounded-lg bg-indigo-600 px-3 text-xs text-white hover:bg-indigo-700"
                      >
                        <Link to="/pricing">Upgrade to Pro</Link>
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Meta: category + effort on mobile */}
            <div className="flex items-center gap-3 text-xs text-muted-foreground">
              <span>Category: <span className="font-medium text-foreground">{finding.category}</span></span>
              <span>&middot;</span>
              <span>Effort: <span className="font-medium text-foreground">{getEffortLabel(finding.effort)}</span></span>
              {finding.estimated_lift && finding.estimated_lift !== "0%" && (
                <>
                  <span>&middot;</span>
                  <span>Expected lift: <span className="font-medium text-foreground">{finding.estimated_lift}</span></span>
                </>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );

  if (finding.is_premium) {
    return <PremiumLock>{content}</PremiumLock>;
  }

  return content;
}

import { getScoreBgColor, getScoreColor, formatScore } from "@/lib/score-utils";
import { CRO_PILLARS } from "@/lib/constants";
import { cn } from "@/lib/utils";
import type { CroPillar } from "@/types";

interface PillarProgressBarProps {
  pillar: CroPillar;
  score: number;
  className?: string;
}

export function PillarProgressBar({ pillar, score, className }: PillarProgressBarProps) {
  const config = CRO_PILLARS.find((p) => p.key === pillar);
  if (!config) return null;

  const Icon = config.icon;

  return (
    <div className={cn("flex items-center gap-3", className)}>
      <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />
      <span className="w-36 shrink-0 truncate text-sm text-foreground/80">{config.label}</span>
      <div className="flex-1">
        <div className="h-2 w-full overflow-hidden rounded-full bg-muted/60">
          <div
            className={cn("h-full rounded-full transition-all duration-1000 ease-out", getScoreBgColor(score))}
            style={{ width: `${score}%` }}
          />
        </div>
      </div>
      <span className={cn("w-10 text-right text-sm font-semibold", getScoreColor(score))}>
        {formatScore(score)}
      </span>
    </div>
  );
}

import React from "react";
import { type LucideIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Link } from "react-router-dom";
import { cn } from "@/lib/utils";

interface EmptyStateProps {
  icon: LucideIcon;
  title: string;
  description: string;
  actionLabel?: string;
  actionHref?: string;
  onAction?: () => void;
  className?: string;
}

export const EmptyState = React.forwardRef<HTMLDivElement, EmptyStateProps>(function EmptyState({
  icon: Icon,
  title,
  description,
  actionLabel,
  actionHref,
  onAction,
  className,
}, ref) {
  return (
    <div ref={ref} className={cn("flex flex-col items-center justify-center py-16 text-center", className)}>
      <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-xl border border-border/50 bg-muted/50">
        <Icon className="h-6 w-6 text-muted-foreground" />
      </div>
      <h3 className="text-base font-medium text-foreground">{title}</h3>
      <p className="mt-1.5 max-w-sm text-sm text-muted-foreground">{description}</p>
      {actionLabel && (
        actionHref ? (
          <Button asChild className="mt-5" size="sm">
            <Link to={actionHref}>{actionLabel}</Link>
          </Button>
        ) : (
          <Button className="mt-5" size="sm" onClick={onAction}>{actionLabel}</Button>
        )
      )}
    </div>
  );
});

