                      )}
                    </div>
                    <ChartErrorBoundary fallbackHeight={90}>
                    <ResponsiveContainer width="100%" height={90}>
                      <AreaChart
                        data={scoreTrend}
                        margin={{ top: 4, right: 4, bottom: 0, left: 4 }}
