          </div>
          <div className="animate-fade-in" style={{ animationDelay: "160ms", animationFillMode: "both" }}>
          <KpiCard
            title="Issues Found"
            value={stats?.total_issues ?? 0}
            icon={AlertTriangle}
            iconBg="bg-red-500/8"
            iconColor="text-red-500"
          />
          </div>
          <div className="animate-fade-in" style={{ animationDelay: "240ms", animationFillMode: "both" }}>
          <KpiCard
            title="Quick Wins"
            value={stats?.quick_wins ?? 0}
            icon={Zap}
            iconBg="bg-emerald-500/8"
            iconColor="text-emerald-500"
          />
          </div>
        </div>

        {/* ── Main 3-column grid ───────────────────────────────── */}
        <div className="grid grid-cols-1 gap-5 lg:grid-cols-3">
          {/* Left: Recent Scans Table (2 cols) */}
