import { useState, useRef, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { generateAuditPDF } from "@/lib/pdf-generator";
import {
  Download,
  Share2,
  RefreshCw,
  ArrowLeft,
  Globe,
  Calendar,
  AlertCircle,
  Zap,
  TrendingUp,
  Copy,
  Check,
  BarChart2,
  Lock,
  Twitter,
  Linkedin,
  Medal,
} from "lucide-react";
import { useFeatureFlag } from "@/hooks/use-feature-flag";
import { ShareScoreModal } from "@/components/shared/ShareScoreModal";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { PillarProgressBar } from "@/components/shared/PillarProgressBar";
import { FindingCard } from "@/components/shared/FindingCard";
import { BrowserFrame } from "@/components/shared/BrowserFrame";
import { PageTransition } from "@/components/shared/PageTransition";
import { SeverityBadge } from "@/components/shared/SeverityBadge";
import {
  getScoreColor,
  getScoreBgLight,
  getScoreLabel,
  getPercentileRank,
  getIndustryBenchmark,
  formatScore,
  getEffortLabel,
  getEffortColor,
  getScoreBgColor,
} from "@/lib/score-utils";
import { CRO_PILLARS } from "@/lib/constants";
import { useAuth } from "@/contexts/AuthContext";
import { useScan, useRefreshScan } from "@/hooks/use-scans";
import { useScanResults } from "@/hooks/use-scan-results";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import type { Finding, Severity } from "@/types";

// ── Helpers ─────────────────────────────────────────────────────

function formatDateTime(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function deviceLabel(device: string) {
  if (device === "both") return "Desktop & Mobile";
  return device === "desktop" ? "Desktop" : "Mobile";
}

/** Annotation dots positioned over the browser mockup to simulate real audit marks */
const ANNOTATION_DOTS: {
  id: string;
  label: string;
  severity: Severity;
  top: string;
  left: string;
}[] = [
  { id: "a1", label: "CTA below fold", severity: "critical", top: "62%", left: "50%" },
  { id: "a2", label: "Low contrast button", severity: "critical", top: "64%", left: "54%" },
  { id: "a3", label: "No social proof", severity: "critical", top: "18%", left: "75%" },
  { id: "a4", label: "Generic headline", severity: "warning", top: "12%", left: "35%" },
  { id: "a5", label: "Missing trust badges", severity: "critical", top: "85%", left: "48%" },
  { id: "a6", label: "Stock photos", severity: "critical", top: "72%", left: "22%" },
  { id: "a7", label: "Weak subheadline", severity: "warning", top: "20%", left: "38%" },
  { id: "a8", label: "Features compete with hero", severity: "warning", top: "44%", left: "50%" },
];

const severityDotColor: Record<Severity, string> = {
  critical: "bg-red-500 border-red-300 shadow-red-500/40",
  warning: "bg-amber-500 border-amber-300 shadow-amber-500/40",
  info: "bg-blue-500 border-blue-300 shadow-blue-500/40",
  passed: "bg-green-500 border-green-300 shadow-green-500/40",
};

// ── Copy Button ─────────────────────────────────────────────────

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);

  const handleCopy = async () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      const textarea = document.createElement("textarea");
      textarea.value = text;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
    }
    setCopied(true);
    timerRef.current = setTimeout(() => setCopied(false), 2000);
  };

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            onClick={handleCopy}
            className={cn(
              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
              copied
                ? "bg-green-50 text-green-600 border border-green-200"
                : "bg-card/80 text-slate-500 border border-border/50 hover:bg-muted/40 hover:text-foreground"
            )}
          >
            {copied ? (
              <><Check className="h-3 w-3" />Copied</>
            ) : (
              <><Copy className="h-3 w-3" />Copy</>
            )}
          </button>
        </TooltipTrigger>
        <TooltipContent side="top">
          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

// ── Enhanced Finding Wrapper ────────────────────────────────────

function EnhancedFinding({ finding }: { finding: Finding }) {
  return (
    <div className="relative">
      <div className="absolute -top-2.5 right-4 z-10 flex items-center gap-1.5">
        <span
          className={cn(
            "inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide",
            getEffortColor(finding.effort)
          )}
        >
          <Zap className="h-2.5 w-2.5" />
          {getEffortLabel(finding.effort)}
        </span>
        {finding.estimated_lift && finding.estimated_lift !== "0%" && (
          <span className="inline-flex items-center gap-1 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide text-violet-600">
            <TrendingUp className="h-2.5 w-2.5" />
            {finding.estimated_lift}
          </span>
        )}
      </div>
      <FindingCard finding={finding} />
      {!finding.is_premium && finding.ai_suggestion && (
        <div className="absolute bottom-5 right-5">
          <CopyButton text={finding.ai_suggestion} />
        </div>
      )}
    </div>
  );
}

// ── Stat Card ───────────────────────────────────────────────────

function StatCard({
  label,
  value,
  icon: Icon,
  accent,
  subtitle,
}: {
  label: string;
  value: string | number;
  icon: React.ElementType;
  accent: string;
  subtitle?: string;
}) {
  return (
    <Card className="border-border/50 shadow-none">
      <CardContent className="flex items-center gap-3.5 p-4">
        <div className={cn("flex h-10 w-10 shrink-0 items-center justify-center rounded-lg", accent)}>
          <Icon className="h-4.5 w-4.5" />
        </div>
        <div className="min-w-0">
          <p className="text-2xl font-bold leading-tight text-foreground">{value}</p>
          <p className="text-xs text-muted-foreground">{label}</p>
          {subtitle && (
            <p className="mt-0.5 text-2xs font-medium text-muted-foreground/70">{subtitle}</p>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

// ── Pillar Bar with Benchmark ───────────────────────────────────

function PillarBarWithBenchmark({
  pillar,
  score,
  benchmark,
}: {
  pillar: string;
  score: number;
  benchmark: number;
}) {
  const config = CRO_PILLARS.find((p) => p.key === pillar);
  if (!config) return null;

  const Icon = config.icon;
  const diff = score - benchmark;
  const diffLabel = diff >= 0 ? `+${diff}` : `${diff}`;
  const diffColor = diff >= 0 ? "text-green-600" : "text-red-500";

  return (
    <div className="group">
      <div className="flex items-center gap-3">
        <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />
        <span className="w-36 shrink-0 truncate text-sm text-foreground/80">{config.label}</span>
        <div className="relative flex-1">
          <div className="h-2.5 w-full overflow-hidden rounded-full bg-muted/50">
            <div
              className={cn("h-full rounded-full transition-all duration-1000 ease-out", getScoreBgColor(score))}
              style={{ width: `${score}%` }}
            />
          </div>
          <TooltipProvider delayDuration={100}>
            <Tooltip>
              <TooltipTrigger asChild>
                <div
                  className="absolute top-1/2 -translate-y-1/2 h-5 w-0.5 bg-slate-800/60 rounded-full"
                  style={{ left: `${benchmark}%` }}
                >
                  <div className="absolute -top-1 left-1/2 -translate-x-1/2 h-1.5 w-1.5 rounded-full bg-slate-700" />
                </div>
              </TooltipTrigger>
              <TooltipContent side="top" className="text-xs">
                <p>Industry avg: {benchmark}/100</p>
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </div>
        <span className={cn("w-10 text-right text-sm font-semibold", getScoreColor(score))}>
          {formatScore(score)}
        </span>
        <span className={cn("w-12 text-right text-xs font-medium", diffColor)}>
          {diffLabel} avg
        </span>
      </div>
    </div>
  );
}

// ── Loading Skeleton ────────────────────────────────────────────

function AuditReportSkeleton() {
  return (
    <div className="space-y-8">
      <Skeleton className="h-4 w-32" />
      <div className="space-y-3">
        <Skeleton className="h-8 w-72" />
        <Skeleton className="h-4 w-48" />
        <Skeleton className="h-4 w-56" />
      </div>
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        {[1, 2, 3, 4].map((i) => <Skeleton key={i} className="h-20" />)}
      </div>
      <Skeleton className="h-64" />
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-5">
        <Skeleton className="h-96 lg:col-span-3" />
        <Skeleton className="h-96 lg:col-span-2" />
      </div>
      <Skeleton className="h-[600px]" />
    </div>
  );
}

// ── Main Component ──────────────────────────────────────────────

const AuditReport = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [isPdfLoading, setIsPdfLoading] = useState(false);
  const pdfExportEnabled = useFeatureFlag("pdf_export_enabled", false);
  const [linkCopied, setLinkCopied] = useState(false);
  const [shareModalOpen, setShareModalOpen] = useState(false);
  const linkCopyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (linkCopyTimerRef.current) clearTimeout(linkCopyTimerRef.current); }, []);

  const { profile } = useAuth();
  const { data: scan, isLoading: scanLoading, error: scanError } = useScan(id);
  const { data: pillarResults = [], isLoading: resultsLoading } = useScanResults(id);
  const refreshScan = useRefreshScan();

  const isLoading = scanLoading || resultsLoading;

  // Loading state
  if (isLoading) {
    return (
      <PageTransition>
        <AuditReportSkeleton />
      </PageTransition>
    );
  }

  // Error or not found state
  if (scanError || !scan) {
    return (
      <PageTransition>
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-muted/50">
            <AlertCircle className="h-8 w-8 text-muted-foreground" />
          </div>
          <h2 className="text-xl font-bold text-foreground">Report not found</h2>
          <p className="mt-2 max-w-sm text-sm text-muted-foreground">
            This scan may have been deleted or hasn't finished processing yet.
          </p>
          <div className="mt-6 flex gap-3">
            <Button variant="outline" asChild>
              <Link to="/reports">View All Reports</Link>
            </Button>
            <Button asChild>
              <Link to="/scan">Run New Scan</Link>
            </Button>
          </div>
        </div>
      </PageTransition>
    );
  }

  // Sort pillars by score ascending (worst first)
  const sortedPillars = [...pillarResults].sort((a, b) => a.score - b.score);

  // Aggregate stats
  const allFindings = pillarResults.flatMap((p) => p.findings);
  const totalFindings = allFindings.length;
  const criticalCount = allFindings.filter((f) => f.severity === "critical").length;
  const quickWinCount = allFindings.filter((f) => f.effort === "quick" && f.severity !== "passed").length;
  const lockedFindings = allFindings.filter((f) => f.is_premium).length;

  // Estimated total lift
  const estimatedTotalLift = allFindings.reduce((sum, f) => {
    const match = f.estimated_lift.match(/(\d+(?:\.\d+)?)-?(\d+(?:\.\d+)?)?%/);
    if (match) {
      const low = parseFloat(match[1]);
      const high = match[2] ? parseFloat(match[2]) : low;
      return sum + (low + high) / 2;
    }
    return sum;
  }, 0);

  // Key issues for sidebar
  const criticalFindings = allFindings
    .filter((f) => f.severity === "critical" || f.severity === "warning")
    .sort((a, b) => {
      const order: Record<Severity, number> = { critical: 0, warning: 1, info: 2, passed: 3 };
      return order[a.severity] - order[b.severity];
    })
    .slice(0, 5);

  const score = scan.overall_score ?? 0;
  const percentile = getPercentileRank(score);
  const scoreLabel = getScoreLabel(score);

  const scansRemaining = (profile?.scan_limit ?? 0) - (profile?.scans_used ?? 0);

  const handleRescan = () => {
    refreshScan.mutate(
      { url: scan.url, page_type: scan.page_type },
      {
        onSuccess: (newScan) => {
          toast.success("Re-scan started");
          navigate(`/scan?url=${encodeURIComponent(scan.url)}&type=${scan.page_type}`);
        },
        onError: () => toast.error("Failed to start re-scan"),
      }
    );
  };

  return (
    <PageTransition>
      <div className="space-y-8">
        {/* ── Breadcrumb ──────────────────────────────────────── */}
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Button variant="ghost" size="sm" asChild className="text-muted-foreground -ml-2 h-auto p-1">
            <Link to="/reports">
              <ArrowLeft className="mr-1 h-3.5 w-3.5" />
              Reports
            </Link>
          </Button>
          <span className="text-muted-foreground/40">/</span>
          <span className="truncate text-slate-500">
            {scan.page_title ?? scan.url}
          </span>
        </div>

        {/* ── Report Header ───────────────────────────────────── */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div className="space-y-2">
            <h1 className="text-3xl font-bold tracking-tight text-foreground leading-tight sm:text-4xl">
              {scan.page_title ?? "Audit Report"}
            </h1>
            <div className="flex items-center gap-2">
              <Globe className="h-3.5 w-3.5 text-muted-foreground" />
              <a
                href={scan.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-primary hover:underline truncate max-w-md"
              >
                {scan.url}
              </a>
            </div>
            <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
              <div className="flex items-center gap-1">
                <Calendar className="h-3.5 w-3.5" />
                {scan.completed_at ? formatDateTime(scan.completed_at) : "In progress"}
              </div>
              <Separator orientation="vertical" className="h-3.5" />
              <Badge variant="outline" className="text-xs capitalize">
                {scan.page_type} page
              </Badge>
              <Badge variant="outline" className="text-xs">
                {deviceLabel(scan.device)}
              </Badge>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              className="border-border/50"
              onClick={() => setShareModalOpen(true)}
            >
              <Medal className="mr-1.5 h-3.5 w-3.5" />
              Share Score
            </Button>
            {pdfExportEnabled ? (
              <Button
                variant="outline"
                size="sm"
                className="border-border/50"
                disabled={isPdfLoading}
                onClick={async () => {
                  if (!scan || pillarResults.length === 0) {
                    toast.error("Report data not ready yet. Please wait.");
                    return;
                  }
                  setIsPdfLoading(true);
                  try {
                    await new Promise<void>((resolve) => {
                      setTimeout(() => {
                        generateAuditPDF(scan, pillarResults, {
                          full_name: profile?.full_name ?? "User",
                          company_name: profile?.company_name ?? undefined,
                        });
                        resolve();
                      }, 0);
                    });
                    toast.success("PDF report downloaded.");
                  } catch (err) {
                    console.error("PDF generation failed:", err);
                    toast.error("Failed to generate PDF. Please try again.");
                  } finally {
                    setIsPdfLoading(false);
                  }
                }}
              >
                {isPdfLoading ? (
                  <RefreshCw className="mr-1.5 h-3.5 w-3.5 animate-spin" />
                ) : (
                  <Download className="mr-1.5 h-3.5 w-3.5" />
                )}
                {isPdfLoading ? "Generating…" : "PDF Report"}
              </Button>
            ) : (
              <Badge
                variant="outline"
                className="border-border/50 text-muted-foreground text-xs px-3 py-1.5 h-9 flex items-center gap-1.5 cursor-not-allowed"
                title="PDF export is currently disabled"
              >
                <Download className="h-3.5 w-3.5" />
                PDF Coming Soon
              </Badge>
            )}
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm" className="border-border/50">
                  <Share2 className="mr-1.5 h-3.5 w-3.5" />
                  Share
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-52">
                <DropdownMenuItem
                  onClick={async () => {
                    try {
                      await navigator.clipboard.writeText(window.location.href);
                      if (linkCopyTimerRef.current) clearTimeout(linkCopyTimerRef.current);
                      setLinkCopied(true);
                      linkCopyTimerRef.current = setTimeout(() => setLinkCopied(false), 2000);
                      toast.success("Link copied to clipboard!");
                    } catch {
                      toast.error("Could not copy link automatically.");
                    }
                  }}
                >
                  {linkCopied ? (
                    <Check className="mr-2 h-4 w-4 text-green-600" />
                  ) : (
                    <Copy className="mr-2 h-4 w-4" />
                  )}
                  {linkCopied ? "Link copied!" : "Copy Link"}
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  onClick={() => {
                    const score = scan?.overall_score ?? 0;
                    const text = encodeURIComponent(
                      `My website scored ${score}/100 on a ConvertScan CRO audit! Check yours at convertscan.com`
                    );
                    const url = encodeURIComponent(window.location.href);
                    window.open(
                      `https://twitter.com/intent/tweet?text=${text}&url=${url}`,
                      "_blank",
                      "noopener,noreferrer"
                    );
                  }}
                >
                  <Twitter className="mr-2 h-4 w-4" />
