          </h2>
          <p className="text-sm text-slate-400 leading-relaxed mb-10">
            Paste any URL. Get a scored audit across 7 CRO pillars with specific, prioritized fixes — not vague advice.
          </p>
          <ul className="space-y-5">
            {[
              { icon: Zap, title: "Results in 30 seconds", desc: "AI scans your page faster than any consultant" },
              { icon: BarChart3, title: "7 CRO pillars scored", desc: "Value prop, CTAs, trust, mobile, copy, and more" },
              { icon: ShieldCheck, title: "Actionable fixes, not reports", desc: "Every finding includes a specific rewrite or change" },
            ].map(({ icon: Icon, title, desc }) => (
              <li key={title} className="flex items-start gap-4">
